// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate/spring

const { fontFamily: interFamily } = loadInter();



export type ComponentNameProps = Record<string, any>;

const Step: React.FC<{
  cx: number;
  cy: number;
  radius: number;
  primaryColor: string;
  textColor: string;
  number: string;
  label: string;
  startFrame: number;
  frame: number;
  fps: number;
  s: number;
  font: string;
}> = ({ cx, cy, radius, primaryColor, textColor, number, label, startFrame, frame, fps, s, font }) => {
  const enterProgress = spring({
    frame: frame - startFrame,
    fps,
    config: { damping: 14, mass: 0.8, stiffness: 120 }
  });

  const opacity = interpolate(
    frame,
    [startFrame, startFrame + 10],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <div
      style={{
        position: 'absolute',
        left: cx - radius,
        top: cy - radius,
        width: radius * 2,
        height: radius * 2,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        transform: `scale(${enterProgress})`,
        opacity: frame >= startFrame ? opacity : 0,
        transition: 'none',
        fontFamily: font
      }}
    >
      <svg width={radius * 2} height={radius * 2} style={{ position: 'absolute', top: 0, left: 0 }}>
        <circle
          cx={radius}
          cy={radius}
          r={radius - 2 * s}
          fill="transparent"
          stroke={primaryColor}
          strokeWidth={Math.max(2 * s, radius * 0.03)}
        />
      </svg>
      <span
        style={{
          color: primaryColor,
          fontSize: radius * 1.05,
          fontWeight: 800,
          lineHeight: 1,
          zIndex: 1,
          transform: `translateY(${radius * 0.06}px)`
        }}
      >
        {number}
      </span>
      <span
        style={{
          position: 'absolute',
          top: radius * 2 + radius * 0.25,
          color: textColor,
          fontSize: Math.max(16 * s, radius * 0.26),
          fontWeight: 700,
          letterSpacing: 2 * s,
          whiteSpace: 'nowrap'
        }}
      >
        {label}
      </span>
    </div>
  );
};

const Arrow: React.FC<{
  startX: number;
  endX: number;
  cy: number;
  color: string;
  startFrame: number;
  frame: number;
  s: number;
}> = ({ startX, endX, cy, color, startFrame, frame, s }) => {
  const duration = 15;
  const progress = interpolate(
    frame,
    [startFrame, startFrame + duration],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  const totalWidth = endX - startX;
  if (totalWidth <= 0) return null;

  const currentWidth = progress * totalWidth;
  const isVisible = frame >= startFrame;

  return (
    <div
      style={{
        position: 'absolute',
        left: startX,
        top: cy - 20 * s,
        width: totalWidth,
        height: 40 * s,
        opacity: isVisible ? 1 : 0,
        transition: 'none'
      }}
    >
      <svg width={totalWidth + 20 * s} height={40 * s} overflow="visible" style={{ position: 'absolute', top: 0, left: 0 }}>
        <line
          x1={0}
          y1={20 * s}
          x2={currentWidth}
          y2={20 * s}
          stroke={color}
          strokeWidth={4 * s}
          strokeDasharray={`${6 * s} ${8 * s}`}
          strokeLinecap="round"
        />
        <g transform={`translate(${currentWidth}, ${20 * s})`}>
          <polygon points={`-${12 * s},-${8 * s} ${4 * s},0 -${12 * s},${8 * s}`} fill={color} />
        </g>
      </svg>
    </div>
  );
};

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = true,
  primaryColor = "#f8b82e",
  textColor = "#ffffff",
  titleText = "ENTIRE FINANCIAL SYSTEM",
  steps = [
    { number: "1", label: "TRUST" },
    { number: "2", label: "DEPOSITS" },
    { number: "3", label: "LOANS" }
  ],
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout constants dynamically calculated to fit up to ~6 steps safely
  const centerX = width / 2;
  const centerY = height / 2 + 50 * s;

  const dynamicGap = Math.min(450 * s, (width * 0.85) / Math.max(1, steps.length - 1));
  const dynamicRadius = Math.min(135 * s, dynamicGap * 0.35);
  const arrowPadding = dynamicRadius * 0.22;

  const totalSpan = (steps.length - 1) * dynamicGap;
  const startX = centerX - totalSpan / 2;

  // Timings
  const titleStart = 5;
  const stepStartOffset = 20;
  const stepStagger = 35;

  const titleOpacity = interpolate(
    frame,
    [titleStart, titleStart + 20],
    [0, 1],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  const titleY = interpolate(
    frame,
    [titleStart, titleStart + 20],
    [180 * s, 140 * s],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      {/* Title Header */}
      <div
        style={{
          position: 'absolute',
          top: titleY,
          width: '100%',
          display: 'flex',
          justifyContent: 'center',
          opacity: frame >= titleStart ? titleOpacity : 0,
          transition: 'none'
        }}
      >
        <span
          style={{
            color: textColor,
            fontSize: 72 * s,
            fontWeight: 800,
            letterSpacing: 2 * s,
            fontFamily: interFamily,
            maxWidth: '85%',
            textAlign: 'center',
            lineHeight: 1.2
          }}
        >
          {titleText}
        </span>
      </div>

      {/* Steps and Connectors */}
      {steps.map((step, index) => {
        const cx = startX + index * dynamicGap;
        const stepStartFrame = stepStartOffset + index * stepStagger;

        return (
          <React.Fragment key={index}>
            {/* Arrow connecting previous step to this step */}
            {index > 0 && (
              <Arrow
                startX={cx - dynamicGap + dynamicRadius + arrowPadding}
                endX={cx - dynamicRadius - arrowPadding}
                cy={centerY}
                color={primaryColor}
                startFrame={stepStartFrame - 15}
                frame={frame}
                s={s}
              />
            )}

            {/* The Circle Step */}
            <Step
              cx={cx}
              cy={centerY}
              radius={dynamicRadius}
              primaryColor={primaryColor}
              textColor={textColor}
              number={step.number}
              label={step.label}
              startFrame={stepStartFrame}
              frame={frame}
              fps={fps}
              s={s}
              font={interFamily}
            />
          </React.Fragment>
        );
      })}
    </AbsoluteFill>
  );
};

export default ComponentName;